CREATE TABLE dim_customer (
    customer_sk      BIGINT IDENTITY(1,1) PRIMARY KEY,  -- surrogate key (per version)
    customer_id      VARCHAR(20)   NOT NULL,            -- natural / business key
    customer_name    VARCHAR(100),
    city             VARCHAR(50),
    region           VARCHAR(50),
    effective_date   DATE          NOT NULL,            -- version start
    end_date         DATE          NOT NULL DEFAULT '9999-12-31', -- high-water mark
    is_current       CHAR(1)       NOT NULL DEFAULT 'Y',
    row_hash         CHAR(64)      NOT NULL             -- SHA-256 over tracked cols
);

CREATE INDEX ix_dim_customer_nk_current ON dim_customer (customer_id, is_current);
CREATE INDEX ix_dim_customer_nk_dates   ON dim_customer (customer_id, effective_date, end_date);
